#!/usr/bin/env node
/**
 * Is campaign mail reaching Microsoft inboxes, or Defender quarantine?
 *
 * There is no Microsoft mailbox available to seed, and the one that was tested has had a
 * tenant-level "not phishing" override applied, so it will now land in the inbox regardless
 * and proves nothing.
 *
 * The idea was that an out-of-office is only generated by a message that reached a mailbox, so
 * the OOO rate from Microsoft-hosted recipients would be a free placement test across hundreds
 * of tenants.
 *
 * IT DOES NOT WORK, and the first run looked like it did. Measured rates were Microsoft 0.13%,
 * Google 0.08%, everything else 3.34%, which reads as both big providers filtering almost
 * everything. The real explanation is tenant configuration: Microsoft 365 and Google Workspace
 * both default to NOT sending automatic replies to external senders, while small and
 * self-hosted mail servers reply to everyone. The gap measures default OOO policy, not
 * placement.
 *
 * Use the human reply column instead. It is not confounded that way, but it is very thin:
 * Microsoft 0.13% (2 of 1529) against Google 0.57% (7 of 1234). Directionally consistent with
 * the confirmed Defender quarantine, nowhere near significant at n=2.
 *
 * Resend's "delivered" cannot answer this: Defender accepts the message and then quarantines
 * it, so quarantined mail is counted as delivered.
 *
 *   node check-ms-placement.js
 *   node check-ms-placement.js --table tempo_leads
 */
require('dotenv').config();
const fs = require('fs');
const supabase = require('./lib/supabase');
const { autoresponderReason } = require('./reply-processor');

const TABLE = process.argv.includes('--table') ? process.argv[process.argv.indexOf('--table') + 1] : 'leads';
const EVENTS = TABLE === 'tempo_leads' ? 'tempo_email_events' : 'email_events';
const FIX_DATE = '2026-08-18';

/** Microsoft-hosted if the MX points at the Exchange Online frontend. */
function hostFromMx(records) {
  const mx = records.map(r => String(r || '').toLowerCase()).join(' ');
  if (/mail\.protection\.outlook\.com|outlook\.com/.test(mx)) return 'microsoft';
  if (/google\.com|googlemail\.com/.test(mx)) return 'google';
  if (!mx.trim()) return 'none';
  return 'other';
}

// Resolving several thousand domains takes minutes and the result never changes, so it is
// cached on disk. Delete the file to force a refresh.
const CACHE_FILE = '.mx-cache.json';
const cache = new Map(Object.entries(
  fs.existsSync(CACHE_FILE) ? JSON.parse(fs.readFileSync(CACHE_FILE, 'utf8')) : {}));

const withTimeout = (p, ms) => Promise.race([p, new Promise(r => setTimeout(() => r(null), ms))]);

async function hostFor(domain) {
  if (cache.has(domain)) return cache.get(domain);
  let host = 'unknown';
  // Plain DNS is blocked in this environment (ECONNREFUSED on every lookup), so MX comes over
  // DNS-over-HTTPS instead. Without this the whole run returns 'timeout' for every domain,
  // which looks like a result and is not one.
  try {
    const res = await withTimeout(
      fetch(`https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`), 6000);
    if (!res) host = 'timeout';
    else {
      const j = await res.json();
      const answers = (j.Answer || []).map(a => a.data);
      host = answers.length ? hostFromMx(answers) : 'none';
    }
  } catch { host = 'none'; }
  cache.set(domain, host);
  return host;
}

const page = async (t, cols) => {
  let a = [], f = 0;
  for (;;) {
    const { data, error } = await supabase.from(t).select(cols).range(f, f + 999);
    if (error) throw new Error(error.message);
    a = a.concat(data);
    if (data.length < 1000) break;
    f += 1000;
  }
  return a;
};

(async () => {
  const ev = await page(EVENTS, 'lead_id,event_type,created_at,metadata');
  const leads = await page(TABLE, 'id,email');
  const emailById = Object.fromEntries(leads.map(l => [l.id, l.email]));

  const sends = ev.filter(e => e.event_type === 'sent');
  const autoByLead = new Set();
  for (const e of ev.filter(e => e.event_type === 'replied')) {
    const m = e.metadata || {};
    const isAuto = m.intent === 'auto_reply'
      || !!autoresponderReason(m.subject || '', m.reply_text || m.snippet || '');
    if (isAuto) autoByLead.add(`${e.lead_id}|${String(e.created_at).slice(0, 10)}`);
  }
  // An autoresponder within 3 days of a send is attributable to that send.
  const autoDates = [...autoByLead].map(k => k.split('|'));
  const hasAutoAfter = (leadId, sentAt) => autoDates.some(([id, d]) =>
    id === leadId && new Date(d) >= new Date(String(sentAt).slice(0, 10))
    && (new Date(d) - new Date(String(sentAt).slice(0, 10))) / 86400000 <= 3);

  const domains = [...new Set(sends.map(s => String(emailById[s.lead_id] || '').split('@')[1]).filter(Boolean))];
  process.stderr.write(`resolving MX for ${domains.length} domains...\n`);
  const CONC = 60;
  for (let i = 0; i < domains.length; i += CONC) {
    await Promise.all(domains.slice(i, i + CONC).map(d => hostFor(d)));
    if (i % 600 === 0) {
      process.stderr.write(`  ${i}/${domains.length}
`);
      fs.writeFileSync(CACHE_FILE, JSON.stringify(Object.fromEntries(cache)));
    }
  }
  fs.writeFileSync(CACHE_FILE, JSON.stringify(Object.fromEntries(cache)));

  const buckets = {};
  for (const s of sends) {
    const email = emailById[s.lead_id];
    if (!email) continue;
    const host = cache.get(String(email).split('@')[1]) || 'unknown';
    const era = String(s.created_at).slice(0, 10) < FIX_DATE ? 'html' : 'plaintext';
    const k = `${host}|${era}`;
    buckets[k] = buckets[k] || { sent: 0, auto: 0 };
    buckets[k].sent++;
    if (hasAutoAfter(s.lead_id, s.created_at)) buckets[k].auto++;
  }

  console.log(`\n${TABLE}: out-of-office rate by mail host, split at the ${FIX_DATE} plain-text fix`);
  console.log('An OOO only comes back from mail that reached a mailbox. Quarantine produces none.\n');
  console.log('host        era         sent   OOO   rate');
  for (const host of ['microsoft', 'google', 'other', 'none', 'timeout', 'unknown']) {
    for (const era of ['html', 'plaintext']) {
      const b = buckets[`${host}|${era}`];
      if (!b) continue;
      const rate = b.sent ? (b.auto / b.sent * 100).toFixed(2) + '%' : '-';
      console.log(`${host.padEnd(11)} ${era.padEnd(10)} ${String(b.sent).padStart(5)} ${String(b.auto).padStart(5)}   ${rate}`);
    }
  }
  const ms = buckets['microsoft|plaintext'];
  if (!ms || ms.sent < 200) {
    console.log(`\nNot conclusive yet: ${ms ? ms.sent : 0} Microsoft sends since the fix.`);
    console.log('Needs ~200+ to separate a real rate from noise. Re-run in a week.');
  }
})().catch(e => { console.error('failed:', e.message); process.exit(1); });
